                "之寄，不謀同詞，分陝雖重，比此為輕。……乞解州錄，以允民望……’……義康由是代弘為司徒，與之分錄。”卷六三《王曇首傳》：“時兄弘錄尚書事，又為揚州刺史，曇首為上所親委，任兼兩宮。彭城王義康與弘並錄，意常怏怏，又欲得揚州，形於辭旨。以曇首居中，分其權任，愈不悅。……曇首勸弘減府兵力之半以配義康，義康乃悅。”卷六八《彭城王義康傳》：“六年，司徒王弘表義康宜還入輔，徵侍中、都督揚南徐兗三州諸軍事、司徒、錄尚書事，領平北將軍、南徐州刺史，持節如故。二府並置佐領兵，與王弘共輔朝政。弘既多疾，且每事推謙，自是內外衆務，一斷之義康。”"
