                "《宋書》卷九五《索虜傳》：“太祖踐祚，便有志北略。七年三月，詔曰：‘……可簡甲卒五萬，給右將軍到彥之，統安北將軍王仲德、兗州刺史竺靈秀舟師入河，驍騎將軍段宏精騎八千，直指虎牢，豫州刺史劉德武勁勇一萬，以相掎角，後將軍長沙王義欣可權假節，率見力三萬，監徵討諸軍事。便速備辦，月內悉發。’”卷五一《長沙王義欣傳》：“七年，到彥之率大衆入河，義欣進彭城，為衆軍聲援。彥之退敗，青、齊搔擾，將佐慮寇大至，勸義欣委鎮還都，義欣堅志不動。”卷五〇《胡藩傳》：“到彥之北伐，南兗州刺史長沙王義欣進據彭城，藩出戍廣陵，行府州事。”"
