                "九五《索虜傳》：“太祖以前徵虜司馬、南廣平太守尹沖為督司雍並三州豫州之潁川兗州之陳留二郡諸軍事、奮威將軍、司州刺史，戍虎牢。十一月，虜大衆南渡河，彥之敗退，洛陽、滑臺、虎牢諸城並為虜所沒。尹沖及司馬滎陽太守崔模抗節不降，投塹死。沖字子順，天水冀人也。”《魏書》卷四上《世祖紀上》：“十月……義隆司州刺史尹沖墜城死。”卷九七《島夷劉裕傳》：“詔冠軍將軍安頡等率衆自盟津渡，攻金墉，義隆建武將軍杜驥出奔，遂乘勝進攻虎牢，陷之，斬其司州刺史尹沖。”卷三〇《安頡傳》：“劉義隆遣將到彥之率衆寇河南，以援赫連定。……世祖西征赫連定，以頡為冠軍將軍，督諸軍擊彥之。……進攻虎牢，虎牢潰，義隆司州刺史尹沖墜城死。”《宋書》卷六五《吉翰傳》：“時太祖經略河南，以翰為持節、監司雍並三州諸軍事、司州刺史，（輔國）將軍如故。會前鋒諸軍到彥之等敗退。”按：《通鑑》及萬表皆雲尹沖“降魏”，此從《宋書》《魏書》。"
