                "紀》：“四月……以撫軍將軍、雍州刺史武陵王駿為安北將軍、徐州刺史。……六月……安北將軍、徐州刺史武陵王駿加兗州刺史。”卷六《孝武帝紀》：“二十五年，改授都督南兗徐兗青冀幽六州豫州之梁郡諸軍事、安北將軍、徐州刺史，持節如故，北鎮彭城。尋領兗州刺史。”卷七六《王玄謨傳》：“義賓薨，玄謨上表，以彭城要兼水陸，請以皇子撫臨州事，乃以孝武出鎮。”"
