                "新安王子鸞北中郎將、刺史，領南琅邪太守。",
                "《宋書》卷六《孝武帝紀》：“十月甲寅，以車騎將軍、南徐州刺史劉延孫為尚書左僕射、領護軍將軍……以東中郎將新安王子鸞為南徐州刺史。”卷七八《劉延孫傳》：“五年，詔延孫曰：‘舊京樹親，由來常準。卿前出所有別議，今此防久弭，當以還授小兒。’徵延孫為侍中、尚書左僕射，領護軍將軍。……又欲以代朱脩之為荊州，事未行，明年，卒。”卷八〇《始平王子鸞傳》：“大明四年，年五歲……五年，遷北中郎將、南徐州刺史，領南琅邪太守。母殷淑儀，寵傾後宮，子鸞愛冠諸子，凡為上所盼遇者，莫不入子鸞之府、國。及為南徐州，又割吳郡以屬之。”卷八四《孔覬傳》：“庾徽之字景猷，潁川鄢陵人也，自中丞出為新安王子鸞北中郎長史、南東海太守，卒官。”卷五九《江智淵傳》：“出為新安王子鸞北中郎長史、南東海太守，加",
                "拜寧朔將軍，行南徐州事。”《南齊書》卷三三《王僧虔傳》：“出為豫章王子尚撫軍長史，遷散騎常侍，復為新安王子鸞北中郎長史、南東海太守，行南徐州事，二蕃皆帝愛子也。”按：大明八年孝武帝死後子鸞始之鎮，行府州事者有庾徽之、江智淵、王僧虔等，年皆不詳，附於此。"
