              "evidence_lines": [
                "《宋書》卷八《明帝紀》：“四月……驃騎大將軍、江州刺史桂陽王休範進位司空。”卷七九《桂陽王休範傳》：“休範素凡訥，少知解，不為諸兄所齒遇。……及太宗晚年，晉平王休祐以狠戾致禍，建安王休仁以權逼不見容，巴陵王休若素得人情，又以此見害。唯休範謹澀無才能，不為物情所向，故得自保，而常懷憂懼，恆慮禍及。及太宗晏駕，主幼時艱，素族當權，近習秉政，休範自謂宗戚莫二，應居宰輔，事既不至，怨憤彌結。招引勇士，繕治器械，行人經過尋陽者，莫不降意折節，重加問遺，□□留則傾身接引，厚相資給。於是遠近同應，從者如歸。朝廷知其有異志，密相防禦，雖未表形跡，而釁難已成。”"
              ],
