                "建平王景素 遷南徐州。",
                "蔡興宗 四月，都督荊湘雍益梁寧南北秦八州諸軍事、徵西將軍、荊州刺史。未任，閏七月，改中書監。",
                "沈攸之 閏七月，都督荊湘雍益梁寧南北秦八州諸軍事、鎮西將軍、荊州刺史。"
