              "summary_lines": [
                "張敬兒 督雍梁二州郢州之竟陵司州之隨郡諸軍事、輔國將軍、寧蠻校尉、雍州刺史。進號徵虜將軍。"
              ],
              "evidence_lines": [
                "《宋書》卷五〇《張興世傳》：“廢帝元徽三年，徵為通直散騎常侍、左衛將軍。”卷九《後廢帝紀》：“三月……以車騎將軍",
                "張敬兒為雍州刺史。”校勘記：“疑‘車騎’為‘驍騎’之訛。”《南齊書》卷二五《張敬兒傳》：“除驍騎將軍、加輔國將軍。太祖以敬兒人位既輕，不欲便使為襄陽重鎮。敬兒求之不已，乃微動太祖曰：‘沈攸之在荊州，公知其欲何所作？不出敬兒以防之，恐非公之利也。’太祖笑而無言，乃以敬兒為持節、督雍梁二州郢司二郡軍事、雍州刺史，將軍如故。”《廿二史考異》卷二五《南齊書·張敬兒傳》：“雍州刺史常督郢州之竟陵、司州之隨郡，非盡督司、郢二州也。……敬兒初鎮雍州，官徵虜將軍，本傳亦未之及。”按：張敬兒為徵虜將軍見昇明元年荊州條。本傳雲張敬兒初鎮雍州時，“將軍如故”，當為輔國將軍，後乃進號徵虜將軍。"
              ],
