                "《南齊書》卷三《武帝紀》：“八月……以左衛將軍隨郡王子隆為荊州刺史。巴東王子響有罪，遣丹陽尹蕭順之率軍討之，子響伏誅。”卷四〇《魚復侯子響傳》：“子響少好武，在西豫時，自選帶仗左右六十人，皆有膽幹。至鎮，數在內齋殺牛",
                "置酒，與之聚樂。令內人私作錦袍絳襖，欲餉蠻交易器仗。長史劉寅等連名密啓，上敕精檢。寅等懼，欲祕之。子響聞臺使至，不見勅……執寅等於後堂殺之。……上聞之怒，遣衛尉胡諧之、遊擊將軍尹略、中書舍人茹法亮領齋仗數百人，檢捕羣小。……臺軍大敗，尹略死之，官軍引退。上又遣丹陽尹蕭順之領兵繼至，子響部下恐懼，各逃散。子響乃白服降，賜死。時年二十二。……寅字景蕤。”卷三七《胡諧之傳》：“八年，上遣諧之率禁兵討巴東王子響於江陵，兼長史行事。臺軍為子響所敗，有司奏免官，權行軍事如故。復為衛尉。”卷四《隨郡王子隆傳》：“八年，代魚復侯子響為使持節、都督荊雍梁寧南北秦六州、鎮西將軍、荊州刺史。……其年，始興王鑑罷益州，進號督益州。”《南史》卷四四《魚復侯子響傳》：“子響及見順之，欲自申明，順之不許，於射堂縊之。”《南北史合注》卷四五《魚復侯子響傳》李清按：“《南齊書》曰：……乃白衣出降，詔賜死。”蓋蕭子顯著書梁世，故為武帝父順之諱也。”《高僧傳》卷一《釋僧慧傳》：“慧後還荊，遇見鎮西長史劉景蕤，忽泣慟而投之，數日蕤果為刺史所害。”按：《高僧傳》作“鎮西長史劉景蕤”，據子響本傳，子響時為鎮軍將軍，“鎮西”當為“鎮軍”之誤。"
