                "《南齊書》卷六《明帝紀》：“正月……虜攻鍾離，徐州刺史蕭惠休破之。……四月……以新除黃門郎裴叔業為徐州刺史。”卷四六《蕭惠休傳》：“遷侍中，領步兵校尉。”卷五一《裴叔業傳》：“除黃門侍郎。上以叔業有勳誠，封武昌縣伯，五百",
                "戶。仍為持節、督徐州軍事、冠軍將軍、徐州刺史。”《魏書》卷七一《裴叔業傳》：“高祖南巡，車駕次鍾離。鸞拜叔業持節、冠軍將軍、徐州刺史，以水軍入淮。”按：吳表闕裴叔業。"
