                "《魏書》卷七下《高祖紀下》：“（太和）十有九年春正月……平南將軍王肅頻破蕭鸞將，擒其寧州刺史董巒。”卷九八《島夷蕭道成傳》：“（太和）十九年……左將軍元麗大破鸞將，擒其寧州刺史董巒。”卷六一《田益宗傳》：“初，益州內附之後，蕭鸞遣寧州刺史董巒追討之，官軍進擊，執巒並其子景曜，送於行宮。巒，字仲舒。”《南史》卷四四《魚復侯子響傳》：“（永明）七年，為都督、荊州刺史。直閤將軍董蠻粗有氣力，子響要與同行。……上聞而不悅，曰：‘人名蠻，復何容得蘊藉。’乃改名為仲舒。”按：魏太和十九年即齊建武二年，永明十年後郭安明、李慶宗相繼為寧州刺史，蓋皆未之任，寧州刺史仍為董仲舒，故建武三年復以李慶宗為寧州刺史，見次年寧州條。《魏書》雲“巒，字仲舒”，據《南史》，“巒”當為“蠻”，齊武帝改為“仲舒”。萬表誤慶宗為“廣宗”。"
