                "《魏書》卷六六《李崇傳》：“氐楊靈珍遣弟婆羅與子雙領步騎萬餘，襲破武興，與蕭鸞相結。詔崇為使持節、都督隴右諸軍事，率衆數萬討之。……崇多設疑兵，襲剋武興。蕭鸞梁州刺史陰廣宗遣參軍鄭猷、王思考率衆援靈珍。崇大破之，並斬婆羅首，殺千餘人，俘獲猷等，靈珍走奔漢中。”"
