                "《梁書》卷一一《張弘策傳》：“明帝崩，遺詔以高祖為雍州刺史……時長沙宣武王罷益州還，仍為西中郎長史，行郢州事。高祖使弘策到郢，陳計於宣武王……弘策因說王曰：‘……以郢州居中流之要，雍部有戎馬之饒，卿兄弟英武，當今無敵，虎據兩州，參分天下，糾合義兵，為百姓請命，廢昏立明，易於反掌……’王頗不懌而無以拒也。”卷一《武帝紀上》：“時高祖長兄懿罷益州還，仍行郢州事，乃使弘策詣郢，陳計於懿",
                "曰：……郢州控帶荊、湘，西注漢、沔；雍州士馬，呼吸數萬，獸眎其間，以觀天下。……如不早圖，悔無及也。懿聞之變色，心弗之許。”《南齊書》卷六《明帝紀》：“四月……以西中郎長史劉暄為郢州刺史。……七月，帝崩於正福殿……遺詔曰：‘……劉暄可衛尉……’”卷四二《江祏傳》：“劉暄初為寶玄郢州行事，執事過刻。有人獻馬，寶玄欲看之，暄曰：‘馬何用看。’妃索煮肫，帳下諮暄，暄曰：‘且已煮鵝，不煩復此。’寶玄恚曰：‘舅殊無《渭陽》之情。’暄聞之亦不悅。”卷五〇《江夏王寶玄傳》：“永泰元年，還為前將軍，領石頭戍事。未拜，東昏即位，進號鎮軍將軍。”卷七《東昏侯紀》：“八月……南中郎將建安王寶寅為郢州刺史。”卷五〇《鄱陽王寶夤傳》：“東昏即位，為使持節、都督郢司二州軍事、徵虜將軍、郢州刺史。尋進號前將軍。”卷四九《張沖傳》：“東昏即位，出為建安王徵虜長史、輔國將軍、江夏內史，行郢州府州事。”按：據《南齊書》，永泰元年四月前劉暄為寶玄西中郎長史，四月劉暄由長史遷郢州刺史，是後寶夤、張沖各繼為刺史、行事。蕭懿為郢州行事當在劉暄前，而《梁書》雲永泰元年七月蕭衍任雍州刺史後蕭懿仍為西中郎長史，又有張弘策陳計事，疑誤或僞。"
