                "裴植隨其季叔叔業自南兗州入北，仕於元氏。”《檀賓墓誌》（《墓誌集成》三五三》：“兗州高平平陽縣都鄉萑陵里人也。……年始廿，為齊徐州刺史裴叔業啟為府主薄。於時朔馬南侵，吳戈北掃，接矢徐方，交刃州境。自非雄明挺秀，無以委居邊捍，遂表君為渦口戍主。……轉君寧朔將軍、步兵校尉，鎮戍壽春。君識否泰於將來，鑒安危於未兆，知雲臺將崩，葦巢難固，遂同裴氏，送城歸魏。”《梁書》卷二三《長沙王懿傳》：“永元二年，裴叔業據豫州反，授持節、徵虜將軍、督豫州諸軍事、豫州刺史，領歷陽南譙二郡太守，討叔業。叔業懼，降於魏。既而平西將軍崔慧景入寇京邑，奉江夏王寶玄圍臺城。齊室大亂，詔徵懿。……乘勝而進，慧景衆潰，追奔之。授侍中、尚書右僕射，未拜，仍遷尚書令、都督徵討水陸諸軍事，持節、將軍如故。……時東昏肆虐，茹法珍、王咺之等執政，宿臣舊將，並見誅夷，懿既立元勳，獨居朝右，深為法珍等所憚……遂遇禍。”《南史》卷五一《長沙王懿傳》：“叔業懼，遂降魏。武帝時在雍州，遣典籤趙景悅說懿興晉陽之甲，誅君側之罪。懿不答。既而平西將軍崔慧景入寇，奉江夏王寶玄圍臺城，齊室大亂，馳信召懿。懿時方食，投箸而起，率銳卒三千人入援。武帝馳遣虞安福下都說懿曰：‘誅賊之後，則有不賞之功，當明君賢主，尚或難立；況於亂朝，何以自免。若賊滅之後，仍勒兵入宮，行伊、霍故事，此萬世一時。若不欲爾，便放表還歷陽，托以外拒為事，則威振內外，誰敢不從。一朝放兵，受其厚爵，高而無人，必生後悔。’長史徐曜甫亦苦勸，並不從。”《南齊書》卷五七《魏虜傳》：“時王肅僞徵南將軍、豫州都督。朝廷既新失大鎮，荒人往來，詐雲肅欲歸國。少帝詔以肅為使持節、侍中、都督豫徐司三州、右將軍、豫州刺史。”校勘記：“僞，北監本、殿本作為”。疑當作為僞。”卷二〇《陳伯",
