                "《梁書》卷二《武帝紀中》：“正月……司空、楊州刺史臨川王宏進位為太尉。……十一月……降太尉、楊州刺史臨川王宏為驃騎將軍、開府同三司之儀。”卷二二《臨川王宏傳》：“以公事左遷驃騎大將軍，開府同三司之儀、侍中如故。未拜，遷使持節、都督楊徐二州諸軍事、揚州刺史，侍中、將軍如故。”按：據《宏傳》上下文，宏左遷在天監八年，此從《武帝紀》。又《武帝紀》雲宏降為驃騎將軍，而本傳雲降為驃騎大將軍，後又",
