                "“《梁書·武帝紀》：‘天監六年四月分湘廣二州置衡州。’至元帝時置東衡州。《陳書·歐陽頠傳》：‘梁元帝承製，以始興郡為東衡州。’其後遂稱衡州為西衡州，以別於治曲江之東衡州。……雄刺衡州時，尚無東衡州，而稱西衡州者，則是從後追書之耳。”"
