                "《梁書》卷一八《康絢傳》：“魏降人王足陳計，求堰淮水以灌壽陽。……發徐、揚人，率二十戶取五丁以築之。假絢節、都督淮上諸軍事，並護堰作，役人及戰士，有衆二十萬。於鍾離南起浮山，北抵巉石，依岸以築土，合脊於中流。十四年……十一月，魏遣將楊大眼揚聲決堰，絢命諸軍撤營露次以待之。遣其子悅挑戰，斬魏鹹陽王府司馬徐方興，魏軍小卻。十二月，魏遣其尚書僕射李曇定督衆軍來戰，絢與徐州刺史劉思祖等距之。”《魏書》卷五五《劉芳傳》：“芳叔撫之，孫思祖……尚書論功擬封千戶侯。思祖有二婢，美姿容，善歌舞，侍中元暉求之不得，事遂停寢。後除揚烈將軍、遼西太守。思祖於路叛奔蕭衍，衍以思祖為輔國將軍、北徐州刺史，頻寇淮北。數年而死。”"
