                "《梁書》卷一八《康絢傳》：“十五年四月，堰乃成。……初，堰起於徐州界，刺史張豹子宣言於境，謂己必屍其事。既而絢以他官來監作，豹子甚慙。……絢還後，豹子不脩堰，至其秋八月，淮水暴長，堰悉壞決，奔流於海。”同卷《昌義之傳》：“十五年，復以為使持節、都督湘州諸軍事、信威將軍、湘州刺史。其年，改授都督北徐州緣淮諸軍事、平北將軍、北徐州刺史。”《魏書》卷五九《蕭寶夤傳》：“靈太后臨朝，還京師。蕭衍遣其將康絢於浮山堰淮以灌揚徐。除寶夤使持節、都督東討諸軍事、鎮東將軍以討之。……熙平初，賊堰既成，淮水濫溢，將為揚徐之患，寶夤於堰上流更鑿新渠，引注淮澤，水乃小減。……又遣軍主周恭叔率壯士數百，夜渡淮南，焚賊徐州刺史張豹子等十一營，賊衆驚擾，自殺害者甚衆。”卷九八《島夷蕭衍傳》：“初，衍每欲稱兵境上，窺伺邊隙，常為諸將摧破，雖懷進趣之計，而勢力不從。遂於浮山堰淮，規為壽春之害。肅宗詔徵南蕭寶夤率諸將討之，大破衍衆於淮北。（熙平元年）秋九月，堰自潰決，漂其緣淮城戍居民村落十餘萬口，流入於海。”"
