                "《魏書》卷九《肅宗紀》：“（熙平元年）五月……蕭衍衡州刺史張齊寇益州。”卷七〇《傅豎眼傳》：“轉昭武將軍、益州刺史。……肅宗初，屢請解州，乃以元法僧代之。……法僧既至，大失民和。蕭衍遣其信武將軍、衡州刺史張齊因民心之怨，入寇晉壽，頻陷葭萌、小劍諸戍，進圍州城。朝廷以西南為憂，乃驛徵豎眼於淮南。既至，以為右將軍、益州刺史……率步騎三千以討張齊。……豎眼既出梁州，衍冠軍將軍勾道侍、梁州刺史任太洪等十餘將所在拒塞……斬太洪及衍徵虜將軍楊伏錫等首。張齊引兵西退，遂奔葭萌。……齊被重創，奔竄而退。小劍、大劍賊亦捐城西走，益州平。”校勘記：“按張齊，《梁書》卷一七有傳，未曾任衡州刺史，梁之衡州也不在此，疑有誤。”"
