                "《梁書》卷三二《陳慶之傳》：“罷義陽鎮兵，停水陸轉運，江湖諸州並得休息。開田六千頃，二年之後，倉廩充實。高祖每嘉勞之。又表省南司州，復安陸郡，置上明郡。”"
